const calendarItems = $input.all();
const triggerData = $('Execute Workflow Trigger').all()[0]?.json || {};
const events = triggerData.events || [];
const founderProfile = triggerData.founder_profile || {};

const busySlots = calendarItems
  .filter(item => item.json.start && item.json.end)
  .map(item => ({
    start: new Date(item.json.start.dateTime || item.json.start.date),
    end: new Date(item.json.end.dateTime || item.json.end.date),
    summary: item.json.summary || ''
  }));

return [{
  json: {
    events: events,
    founder_profile: founderProfile,
    busy_slots: busySlots,
    founder_location: founderProfile.location || ''
  }
}];

const input = $input.all()[0].json;
const events = input.events || [];
const busySlots = input.busy_slots || [];
const founderLocation = (input.founder_location || '').toLowerCase();
const founderProfile = input.founder_profile || {};

function isAvailable(eventDateStr) {
  if (!eventDateStr) return true;
  const eventDate = new Date(eventDateStr);
  if (isNaN(eventDate.getTime())) return true;
  for (const slot of busySlots) {
    if (eventDate >= slot.start && eventDate <= slot.end) return false;
  }
  return true;
}

function proximityScore(eventLocation) {
  if (!eventLocation || !founderLocation) return 0;
  const loc = eventLocation.toLowerCase();
  if (loc.includes(founderLocation) || founderLocation.includes(loc)) return 10;
  const geoPrefs = (founderProfile.geo_preferences || []).map(g => g.toLowerCase());
  for (const geo of geoPrefs) {
    if (loc.includes(geo) || geo.includes(loc)) return 7;
  }
  if (loc.includes('online') || loc.includes('virtual') || loc.includes('remote')) return 5;
  return 0;
}

const availableEvents = events
  .filter(evt => isAvailable(evt.date))
  .map(evt => {
    const proxScore = proximityScore(evt.location);
    const totalScore = (evt.combined_score || evt.relevancy_score || 0) + (evt.connection_score || 0) + proxScore;
    return { ...evt, proximity_score: proxScore, total_recommendation_score: totalScore };
  })
  .sort((a, b) => b.total_recommendation_score - a.total_recommendation_score);

const weeklyRecs = new Map();
for (const evt of availableEvents) {
  if (!evt.date) continue;
  const evtDate = new Date(evt.date);
  if (isNaN(evtDate.getTime())) continue;
  const weekStart = new Date(evtDate);
  weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
  const weekKey = weekStart.toISOString().split('T')[0];

  if (!weeklyRecs.has(weekKey)) weeklyRecs.set(weekKey, []);
  const weekEvents = weeklyRecs.get(weekKey);
  if (weekEvents.length < 3) {
    const attendeesList = evt.attendees_from_network || [];
    const investorAttendees = attendeesList.filter(a => a.type === 'investor' || true);

    weekEvents.push({
      event_name: evt.event_name,
      date: evt.date,
      location: evt.location,
      url: evt.url,
      why_recommended: [
        evt.relevancy_score > 5 ? 'Highly relevant to your industry and stage' : 'Matches your interest areas',
        evt.connection_score > 0 ? `${attendeesList.length} people from your investor/founder network attending` : null,
        evt.proximity_score >= 10 ? 'In your city' : evt.proximity_score >= 7 ? 'In your preferred region' : evt.proximity_score >= 5 ? 'Virtual event (attend from anywhere)' : 'Requires travel'
      ].filter(Boolean).join('. '),
      likely_attendees: attendeesList.slice(0, 10),
      prep_notes: [
        `Research attending investors/founders beforehand`,
        evt.relevancy_score > 5 ? 'Prepare your pitch deck - high investor concentration expected' : 'Good networking opportunity',
        attendeesList.length > 0 ? `Request warm intros via mutual connections` : 'Bring business cards for cold introductions',
        `Review event agenda and identify key sessions`
      ].join('. '),
      scores: {
        relevancy: evt.relevancy_score || 0,
        connection: evt.connection_score || 0,
        proximity: evt.proximity_score,
        total: evt.total_recommendation_score
      }
    });
  }
}

const weeklyRecommendations = Array.from(weeklyRecs.entries())
  .map(([weekStart, evts]) => ({ week_start: weekStart, events: evts }))
  .sort((a, b) => a.week_start.localeCompare(b.week_start));

return [{
  json: {
    status: 'success',
    weekly_recommendations: weeklyRecommendations,
    total_events_considered: events.length,
    total_events_available: availableEvents.length,
    total_recommended: weeklyRecommendations.reduce((sum, w) => sum + w.events.length, 0)
  }
}];

